import { Pool } from "pg";

export interface Post {
  id: string;
  communityId: string;
  authorId: string;
  body: string;
  createdAt: Date;
  hidden: boolean;
}

interface PostRow {
  id: string;
  community_id: string;
  author_id: string;
  body: string;
  created_at: Date;
  hidden: boolean;
}

function toPost(r: PostRow): Post {
  return {
    id: r.id,
    communityId: r.community_id,
    authorId: r.author_id,
    body: r.body,
    createdAt: r.created_at,
    hidden: r.hidden,
  };
}

export class PostRepository {
  constructor(private readonly db: Pool) {}

  async feed(communityId: string, before: Date, limit: number): Promise<Post[]> {
    const res = await this.db.query<PostRow>(
      `SELECT id, community_id, author_id, body, created_at, hidden
         FROM posts
        WHERE community_id = $1 AND hidden = false AND created_at < $2
        ORDER BY created_at DESC
        LIMIT $3`,
      [communityId, before, limit],
    );
    return res.rows.map(toPost);
  }

  async findById(communityId: string, postId: string): Promise<Post | null> {
    const res = await this.db.query<PostRow>(
      `SELECT id, community_id, author_id, body, created_at, hidden
         FROM posts
        WHERE id = $1 AND hidden = false`,
      [postId],
    );
    return res.rowCount ? toPost(res.rows[0]) : null;
  }

  async create(communityId: string, authorId: string, body: string): Promise<Post> {
    const res = await this.db.query<PostRow>(
      `INSERT INTO posts (community_id, author_id, body)
       VALUES ($1, $2, $3)
       RETURNING id, community_id, author_id, body, created_at, hidden`,
      [communityId, authorId, body],
    );
    return toPost(res.rows[0]);
  }
}

import express, { NextFunction, Request, Response } from "express";
import { Pool } from "pg";
import { PostRepository } from "./postRepository";

interface Member {
  userId: string;
  communityId: string;
}

declare module "express-serve-static-core" {
  interface Request {
    member?: Member;
  }
}

export function buildRouter(db: Pool, verifySession: (token: string) => Promise<Member | null>) {
  const posts = new PostRepository(db);
  const router = express.Router();

  router.use(async (req: Request, res: Response, next: NextFunction) => {
    const token = req.header("authorization")?.replace(/^Bearer /, "");
    const member = token ? await verifySession(token) : null;
    if (!member) return res.status(401).json({ error: "unauthenticated" });
    req.member = member;
    next();
  });

  router.get("/feed", async (req, res, next) => {
    try {
      const limit = Math.min(Number(req.query.limit) || 20, 100);
      const before = req.query.before ? new Date(String(req.query.before)) : new Date();
      if (Number.isNaN(before.getTime())) return res.status(400).json({ error: "invalid before" });
      const items = await posts.feed(req.member!.communityId, before, limit);
      const nextCursor = items.length === limit ? items[items.length - 1].createdAt.toISOString() : null;
      res.json({ items, nextCursor });
    } catch (err) {
      next(err);
    }
  });

  router.get("/posts/:id", async (req, res, next) => {
    try {
      const post = await posts.findById(req.member!.communityId, req.params.id);
      if (!post) return res.status(404).json({ error: "not found" });
      res.json(post);
    } catch (err) {
      next(err);
    }
  });

  router.post("/posts", express.json({ limit: "16kb" }), async (req, res, next) => {
    try {
      const body = typeof req.body?.body === "string" ? req.body.body.trim() : "";
      if (!body || body.length > 5000) return res.status(400).json({ error: "body must be 1-5000 chars" });
      const post = await posts.create(req.member!.communityId, req.member!.userId, body);
      res.status(201).json(post);
    } catch (err) {
      next(err);
    }
  });

  return router;
}
